function _whSave(TOP,s){ try{ TOP.localStorage.setItem(WKEY, JSON.stringify(s)); return true; }catch(e){ return false; } }
/* 把渲染引擎注入顶层窗口（只注入一次）——引擎常驻 TOP，不随消息 iframe 销毁，
   这样设置里开了之后每次打开 VN 都会显示勾选的特效。 */
function _whInjectEngine(TOP){
  try{
    var d=TOP.document;
    if(d.getElementById('vnm-weather-engine')){ try{ console.info('[VNM天气] _whInjectEngine: 引擎已存在'); }catch(e){} return; }
    var s=d.createElement('script'); s.id='vnm-weather-engine'; s.textContent=ENGINE_SRC;
    (d.head||d.documentElement).appendChild(s);
    try{ console.info('[VNM天气] _whInjectEngine: 已注入引擎('+String(ENGINE_SRC||'').length+'字符)'); }catch(e){}
  }catch(e){ try{ console.warn('[VNM天气] _whInjectEngine 异常:', e); }catch(_e){} }
}
function _whBoot(TOP, ctx){
  var s=_whLoad(TOP);
  s.enabled = !!(ctx.settings && ctx.settings.enabled);
  s.coverDialog = ctx.settings ? (ctx.settings.coverDialog !== false && ctx.settings.coverDialog !== 'false') : true;
  s.autoTags = !!(ctx.settings && ctx.settings.autoTags);
  _whSave(TOP,s);
  try{ console.info('[VNM天气] _whBoot 执行: enabled='+s.enabled+' autoTags='+s.autoTags+' effects='+(s.effects||[]).length); }catch(e){}
  _whInjectEngine(TOP);
}

var TOP = window.parent;
_whBoot(TOP, ctx);
function _whInjectText(){
  var cfg=ctx.settings||{};
  if(!cfg.autoTags) return '';
  var s=_whLoad(TOP);
  var names=(s.effects||[]).map(function(e){return (e.name||'').trim();}).filter(Boolean);
  var tpl=cfg.weatherInjectTemplate||'';
  if(!tpl){
    tpl='【天气系统】当剧情中的天气或环境氛围发生变化时,在场景描写中输出 [天气:特效名] 标签(如 [天气:下雨])。可用特效名:{{天气特效清单}}。天气晴朗或无需特效时输出 [天气:晴]。其余内容正常书写。';
  }
  var list=names.join('、')||'(未导入任何天气特效)';
  if(tpl.indexOf('{{天气特效清单}}')<0) tpl=tpl+'
可用特效:{{天气特效清单}}';
  return tpl.replace(/\{\{天气特效清单\}\}/g, list);
}
return _whInjectText();

})
